import {Pressable,Text,View} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";

/**
 * Labeled on/off row shared by the canvas settings panels: a 44pt switch with
 * the label on the start side and the track on the end side (mirrored in RTL).
 */
export function SettingSwitch({label,on,onChange,disabled,styled,hint}:{
  label:string;on:boolean;onChange:(on:boolean)=>void;disabled:boolean;styled:boolean;hint?:string|undefined;
}){
  return <Pressable role="switch" aria-checked={on} accessibilityRole="switch" accessibilityState={{checked:on,disabled}}
    aria-label={label} accessibilityHint={hint} disabled={disabled} onPress={()=>onChange(!on)}
    {...{className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{minHeight:44,flexDirection:"row",alignItems:"center",justifyContent:"space-between",gap:12,paddingHorizontal:4,opacity:disabled?0.5:1}}>
    <Text {...{className:joinClasses(styled&&"text-text text-sm")}} style={{flexShrink:1}}>{label}</Text>
    <View pointerEvents="none" {...{className:joinClasses(styled&&"border",styled&&(on?"bg-primary border-primary":"bg-surface-sunken border-border"))}}
      style={{width:40,height:24,borderRadius:12,padding:2,justifyContent:"center",alignItems:on?"flex-end":"flex-start"}}>
      <View {...{className:joinClasses(styled&&(on?"bg-on-primary":"bg-text-muted"))}} style={{width:18,height:18,borderRadius:9}}/>
    </View>
  </Pressable>;
}

import { View, type ViewProps } from "react-native";
import { Select } from "@/components/nyc-tron/ui/components/Select";
import { SettingSwitch } from "@/components/nyc-tron/ui/components/forge/canvas/SettingSwitch";
import { validateSoftProof, type ColorProfile, type SoftProofSettings } from "@/components/nyc-tron/ui/components/forge/color/color-management";
export type { SoftProofSettings } from "@/components/nyc-tron/ui/components/forge/color/color-management";
/** Explicit output proof configuration rendered by SoftProofControls. */
export interface SoftProofControlsProps extends Omit<ViewProps, "children"> {
  readonly value: SoftProofSettings;
  readonly profiles: readonly ColorProfile[];
  readonly onCommit: (settings: SoftProofSettings) => void;
  readonly disabled?: boolean;
  readonly unstyled?: boolean;
}
/** Controls a host's proof transform; UI does not pretend to perform ICC conversion. */
export function SoftProofControls({ value, profiles, onCommit, disabled = false, unstyled = false, ...props }: SoftProofControlsProps) {
  validateSoftProof(value, profiles);
  const set = (change: Partial<SoftProofSettings>) => { if (disabled) return; const next = { ...value, ...change }; validateSoftProof(next, profiles); onCommit(next); };
  return <View {...props} style={[{ gap: 8 }, props.style]}>
    <Select label="Proof output profile" value={value.profileId ?? ""} placeholder="Choose a proof profile" options={profiles.map(profile => ({ value: profile.id, label: profile.label }))} disabled={disabled} unstyled={unstyled} onValueChange={profileId => set({ profileId })}/>
    <SettingSwitch label="Enable soft proof" on={value.enabled} onChange={enabled => set({ enabled })} disabled={disabled || value.profileId === null} styled={!unstyled}/>
    <Select label="Rendering intent" value={value.intent} options={(["perceptual", "relative-colorimetric", "saturation", "absolute-colorimetric"] as const).map(value => ({ value, label: value.replaceAll("-", " ") }))} disabled={disabled} unstyled={unstyled} onValueChange={intent => set({ intent: intent as SoftProofSettings["intent"] })}/>
    <SettingSwitch label="Show proof gamut clipping" on={value.showGamutClipping??false} onChange={showGamutClipping=>set({showGamutClipping})} disabled={disabled} styled={!unstyled}/>
    {([['blackPointCompensation', 'Black point compensation'], ['simulatePaper', 'Simulate paper color'], ['simulateBlackInk', 'Simulate black ink']] as const).map(([key, label]) => <SettingSwitch key={key} label={label} on={value[key]} onChange={on => set({ [key]: on })} disabled={disabled} styled={!unstyled}/>)}
  </View>;
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
